import { createHash } from "node:crypto";

/** A snapshot of the fields that may be projected into a recovery summary. */
export interface WorkingContextSnapshot {
  goals?: readonly unknown[];
  unfinishedWork?: readonly unknown[];
  dependencies?: readonly unknown[];
  recentEvidence?: readonly unknown[];
  /** Depth of the handoff chain that produced the snapshot. */
  chainDepth?: number;
  /** Optional explicit depth, useful when the snapshot is not the chain root. */
  depth?: number;
}

export interface ContextPressureRecoveryOptions {
  /** Maximum number of projected items retained in the summary. */
  maxItems?: number;
  /** Maximum accepted handoff-chain depth. */
  maxDepth?: number;
}

export interface ContextPressureRecoverySection {
  goals: readonly unknown[];
  unfinishedWork: readonly unknown[];
  dependencies: readonly unknown[];
  recentEvidence: readonly unknown[];
}

export interface ContextPressureRecoveryCounts {
  goals: { kept: number; dropped: number; total: number };
  unfinishedWork: { kept: number; dropped: number; total: number };
  dependencies: { kept: number; dropped: number; total: number };
  recentEvidence: { kept: number; dropped: number; total: number };
}

export interface ContextPressureRecoveryResult {
  status: "recovered" | "unknown" | "depth-exceeded";
  complete: false;
  truncated: boolean;
  digest: string;
  sections?: ContextPressureRecoverySection;
  counts?: ContextPressureRecoveryCounts;
  reason?: string;
}

const SECTION_NAMES = [
  "goals",
  "unfinishedWork",
  "dependencies",
  "recentEvidence",
] as const;

type SectionName = (typeof SECTION_NAMES)[number];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function asArray(value: unknown): readonly unknown[] {
  return Array.isArray(value) ? value : [];
}

function effectiveDepth(snapshot: WorkingContextSnapshot, depth?: number): number {
  if (typeof depth === "number" && Number.isFinite(depth)) return depth;
  if (typeof snapshot.depth === "number" && Number.isFinite(snapshot.depth)) return snapshot.depth;
  if (typeof snapshot.chainDepth === "number" && Number.isFinite(snapshot.chainDepth)) {
    return snapshot.chainDepth;
  }
  return 0;
}

function canonicalize(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalize);
  if (!isRecord(value)) return value;
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(value).sort()) {
    if (value[key] !== undefined) result[key] = canonicalize(value[key]);
  }
  return result;
}

function digestOf(value: unknown): string {
  return createHash("sha256").update(JSON.stringify(canonicalize(value))).digest("hex");
}

function emptyCounts(): ContextPressureRecoveryCounts {
  return {
    goals: { kept: 0, dropped: 0, total: 0 },
    unfinishedWork: { kept: 0, dropped: 0, total: 0 },
    dependencies: { kept: 0, dropped: 0, total: 0 },
    recentEvidence: { kept: 0, dropped: 0, total: 0 },
  };
}

/**
 * Projects a bounded, deterministic recovery summary from an existing Working
 * Context snapshot. This function never mutates the snapshot and never claims
 * that the underlying task has completed.
 */
export function recoverContextPressure(
  snapshot: WorkingContextSnapshot | null | undefined,
  options: ContextPressureRecoveryOptions = {},
  depth?: number,
): ContextPressureRecoveryResult {
  const maxDepth = options.maxDepth ?? Number.POSITIVE_INFINITY;
  const maxItems = options.maxItems ?? 8;
  if (!Number.isInteger(maxItems) || maxItems < 0) {
    throw new RangeError("maxItems must be a non-negative integer");
  }

  if (!snapshot) {
    return {
      status: "unknown",
      complete: false,
      truncated: false,
      digest: digestOf(null),
      reason: "working-context-snapshot-missing",
    };
  }

  const currentDepth = effectiveDepth(snapshot, depth);
  if (currentDepth > maxDepth) {
    return {
      status: "depth-exceeded",
      complete: false,
      truncated: false,
      digest: digestOf({ depth: currentDepth, maxDepth }),
      reason: "depth-exceeded",
    };
  }

  const counts = emptyCounts();
  const sections: ContextPressureRecoverySection = {
    goals: [],
    unfinishedWork: [],
    dependencies: [],
    recentEvidence: [],
  };
  let remaining = maxItems;
  let truncated = false;
  let total = 0;

  for (const name of SECTION_NAMES) {
    const source = asArray(snapshot[name]);
    const sectionCounts = counts[name];
    sectionCounts.total = source.length;
    total += source.length;
    for (const item of source) {
      if (remaining > 0) {
        (sections[name] as unknown[]).push(item);
        sectionCounts.kept += 1;
        remaining -= 1;
      } else {
        sectionCounts.dropped += 1;
        truncated = true;
      }
    }
  }

  if (total === 0) {
    return {
      status: "unknown",
      complete: false,
      truncated: false,
      digest: digestOf({ snapshot, sections: null }),
      reason: "working-context-snapshot-empty",
    };
  }

  return {
    status: "recovered",
    complete: false,
    truncated,
    digest: digestOf(sections),
    sections,
    counts,
  };
}

export const projectWorkingContextRecovery = recoverContextPressure;
export const projectContextPressureRecovery = recoverContextPressure;
export const recoverWorkingContext = recoverContextPressure;

/** Convenience form that reads the four sections from a generic Working Context. */
export function recoverFromWorkingContext(
  workingContext: unknown,
  options: ContextPressureRecoveryOptions = {},
  depth?: number,
): ContextPressureRecoveryResult {
  if (!isRecord(workingContext)) return recoverContextPressure(undefined, options, depth);
  const snapshot: WorkingContextSnapshot = {
    goals: asArray(workingContext.goals),
    unfinishedWork: asArray(workingContext.unfinishedWork),
    dependencies: asArray(workingContext.dependencies),
    recentEvidence: asArray(workingContext.recentEvidence),
  };
  const chainDepth = workingContext.chainDepth ?? workingContext.depth;
  if (typeof chainDepth === "number") snapshot.chainDepth = chainDepth;
  return recoverContextPressure(snapshot, options, depth);
}

